# Add dedicated deep-dive card to the source article.
for x in items:
    p=ROOT/'notizie'/f"{x['source']}.html"
    s=p.read_text(encoding='utf-8')
    card=f'<a href="/approfondimenti/{x["slug"]}.html"><small>Approfondimento</small><strong>{x["title"]}</strong></a>'
    s=s.replace('<div class="curio-related-grid">','<div class="curio-related-grid">'+card,1)
    p.write_text(s,encoding='utf-8')

# Prepend cards in the index, newest first.
p=ROOT/'approfondimenti/index.html'; s=p.read_text(encoding='utf-8')
cards=''.join(f'<a class="card" href="../approfondimenti/{x["slug"]}.html" data-cm-evergreen-slug="{x["slug"]}"><span class="tag">Approfondimento · {x["tag"]}</span><div><h2>{x["title"]}</h2><p>{x["desc"]}</p></div><b>Leggi l’approfondimento →</b></a>' for x in items)
s=s.replace('<section class="grid">','<section class="grid">'+cards,1); p.write_text(s,encoding='utf-8')

# Search index.
p=ROOT/'assets/data/search-index-v210.json'; data=json.loads(p.read_text(encoding='utf-8')); data['version']=326
data['items']=[{"title":x['title'],"excerpt":x['desc'],"url":f"/approfondimenti/{x['slug']}.html","section":f"Approfondimenti / {x['tag']}"} for x in items]+data['items']
p.write_text(json.dumps(data,ensure_ascii=False,indent=2)+"\n",encoding='utf-8')

# General sitemap only: evergreen pages do not belong in News Sitemap.
p=ROOT/'sitemap.xml'; s=p.read_text(encoding='utf-8')
urls=''.join(f'  <url>\n    <loc>https://curiomondo.it/approfondimenti/{x["slug"]}.html</loc>\n    <lastmod>{DATE}</lastmod>\n    <changefreq>monthly</changefreq>\n    <priority>0.8</priority>\n  </url>\n' for x in items)
s=s.replace('</urlset>',urls+'</urlset>'); p.write_text(s,encoding='utf-8')

# Version state.
p=ROOT/'curiomondo-site-manifest.json'; m=json.loads(p.read_text(encoding='utf-8')); m['site']['current_site_version']=326; m['site']['site_version']=326
p.write_text(json.dumps(m,ensure_ascii=False,indent=2)+"\n",encoding='utf-8')
print('Created',len(items),'deep dives')
